function categoryFor(modId){if(addons.some(a=>a.modId===modId))return 'create';const meta=catalogMods.find(m=>m.modId===modId);if(meta){if(meta.category==='storage')return 'resources';return meta.category;}return 'other';}
function modIcon(id){const candidate=disciplines.flatMap(d=>d.items).find(item=>item.startsWith(id+':')&&icons[item])||recipes.find(r=>r.source.modId===id&&icons[r.output.id])?.output.id;return candidate?icon(candidate):'';}
function catalogName(modId){return addons.find(a=>a.modId===modId)?.name||catalogMods.find(a=>a.modId===modId)?.name||(modId==='minecraft'?'Minecraft':modId==='atm10'?'Especiales de ATM10':modId);}
function featuredRecipes(){const list=[...featured,...disciplines.flatMap(d=>d.items)];return [...new Set(list)].map(id=>engine.choose(id)).filter(Boolean);}
function name(id){id=String(id||'');if(manualNames[id])return manualNames[id];if(id.startsWith('#'))return 'Cualquier '+id.slice(1).split(':').pop().replaceAll('/',' · ').replaceAll('_',' ');const [ns,part]=id.split(':');const base=part||ns;return translations.es_es?.[`item.${ns}.${base}`]||translations.es_es?.[`block.${ns}.${base}`]||translations.en_us?.[`item.${ns}.${base}`]||translations.en_us?.[`block.${ns}.${base}`]||base.replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());}
function engName(id){const [ns,part]=id.split(':');return translations.en_us?.[`item.${ns}.${part}`]||translations.en_us?.[`block.${ns}.${part}`]||id;}
function icon(id){const resolved=id.startsWith('fluid:')?id.slice(6):id;const url=icons[resolved];return url?`<img class="item-icon" src="${esc(url)}" alt="" title="${esc(name(resolved))}" loading="lazy">`:`<span class="item-fallback" role="img" aria-label="Icono no disponible: ${esc(name(resolved))}" title="Icono no disponible para ${esc(name(resolved))}"><svg viewBox="0 0 32 32" fill="none" aria-hidden="true"><path d="m16 4 11 6v13l-11 6-11-6V10Z M5 10l11 6 11-6M16 16v13" stroke="currentColor" stroke-width="1.2"/><path d="m11 7 11 6v5" stroke="currentColor" stroke-width=".8"/></svg><small>?</small></span>`;}

function process(type){return types[type]||type.split(':').pop().replaceAll('_',' ');}
function save(){storageError=!crew.save();}
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000);}
function completed(phase){return phase.tasks.filter(t=>state.tasks[phase.id+':'+t[0]]).length;}
function totalDone(){return phases.reduce((n,p)=>n+completed(p),0);}
function totalTasks(){return phases.reduce((n,p)=>n+p.tasks.length,0);}
function currentPhase(){return phases.find(p=>completed(p)<p.tasks.length)||phases.at(-1);}
function percent(){return Math.round(totalDone()/totalTasks()*100);}
function pageTitle(eyebrow,title,description,action=''){return `<div class="page-title compact-title"><div><h1>${title}</h1>${description?`<p>${description}</p>`:''}</div>${action}</div>`;}

const navItems={home:'minecraft:crafting_table',recipes:'minecraft:chest',animations:'minecraft:book',projects:'create:wrench',mods:'minecraft:bookshelf',mahou:'minecraft:ender_pearl',crew:'minecraft:emerald'};
function nav(){
 const active=id=>view===id||(id==='mods'&&view==='guide')||(id==='recipes'&&view==='item')||(id==='projects'&&view==='project');
 const row=([id,mark,label])=>`<button class="nav-button ${active(id)?'active':''}" data-view="${id}" ${active(id)?'aria-current="page"':''}><span aria-hidden="true">${navItems[id]?icon(navItems[id]):mark}</span>${label}</button>`;
 const primary=['home','recipes','animations','projects','mods','mahou','crew'];
 const secondary=views.filter(v=>!primary.includes(v[0]));
 $('#main-nav').innerHTML=primary.map(id=>row(views.find(v=>v[0]===id))).join('')+`<details class="nav-more" ${secondary.some(v=>active(v[0]))?'open':''}><summary>Más herramientas <span>+</span></summary>${secondary.map(row).join('')}</details>`;
 $('#breadcrumb-current').textContent=views.find(v=>v[0]===view)?.[2]||(view==='guide'?'Guía del mod':view==='project'?'Proyecto y plano':view==='item'?'Atlas de objetos':'Fuentes y versión');
}
function render(){crew.chrome();workshop?.dispose();disposeScene();disposeScene=()=>{};nav();$('#content').innerHTML=({crew:()=>crew.view(),home:homeView,mahou:()=>mahou.view(),animations:animationsView,guide:modGuideView,routes:routesView,recipes:recipesView,item:recipesView,projects:()=>workshop.view('projects'),project:()=>workshop.view('project'),map:()=>workshop.view('map'),production:()=>workshop.view('production'),diagnostics:()=>workshop.view('diagnostics'),play:()=>workshop.view('play'),media:()=>workshop.view('media'),planner:plannerView,inventory:inventoryView,mods:modsView,notes:notesView,sources:sourcesView}[view]||homeView)();workshop?.mount(view);if(view==='animations'&&selectedLesson){const lesson=lessons.find(l=>l.id===selectedLesson);if(lesson)disposeScene=mountScenePlayer($('#lesson-player'),lesson);}}
function navigate(next){
 if(next==='guide/mahoutsukai')return navigate('mahou');
 clearTimeout(searchTimer);
 const slash=next.indexOf('/'),target=slash<0?next:next.slice(0,slash),id=slash<0?'':next.slice(slash+1);
 if(target==='mahou'){view='mahou';mahou.route(decodeURIComponent(id));}
 else if(['project','item'].includes(target)&&id){view=target;workshop.route(target,decodeURIComponent(id));}
 else
 if(target==='guide'&&id){selectedGuide=decodeURIComponent(id);view='guide';if(selectedGuide==='mahoutsukai')mahou.route('');}
 else {view=views.some(v=>v[0]===target)||target==='sources'?target:'home';if(target==='animations'&&id)selectedLesson=decodeURIComponent(id);if(target==='routes'&&id==='star')routeScope='star';}
 history.replaceState(null,'','#'+(view==='mahou'?'mahou'+(id?'/'+id:''):['project','item'].includes(view)?view+'/'+id:view==='guide'?'guide/'+encodeURIComponent(selectedGuide):view==='animations'&&selectedLesson?'animations/'+encodeURIComponent(selectedLesson):view));
 closeMenu();render();window.scrollTo({top:0});if(view==='item'&&window.matchMedia('(max-width:900px)').matches)$('#recipe-results')?.scrollIntoView({block:'start'});
}

function homeView(){const cur=currentPhase();return `
<section class="mc-welcome"><div class="mc-welcome-copy"><span class="eyebrow">TU GUÍA DE ALL THE MODS 10</span><h1>Un bloque.<br>Mil posibilidades.</h1><p>Encuentra una receta, entiende una máquina<br class="desktop-break"> y construye tu siguiente idea.</p><form id="home-search" class="mc-home-search"><span aria-hidden="true">⌕</span><input name="query" type="search" aria-label="Buscar un objeto en el atlas" placeholder="¿Qué quieres construir?" required><button type="submit" aria-label="Buscar en el atlas">→</button></form><div class="mc-popular"><span>Prueba con</span><button data-view="item/minecraft%3Achest">Cofre</button><button data-view="item/create%3Amechanical_press">Prensa</button><button data-view="mahou">Mahou</button></div></div><div class="mc-welcome-art" aria-hidden="true"><div class="mc-art-grid"></div><div class="mc-orbit mc-orbit-back">${icon('minecraft:oak_log')}${icon('minecraft:crafting_table')}${icon('minecraft:furnace')}</div><div class="mc-art-main">${icon('create:mechanical_press')}</div><div class="mc-orbit mc-orbit-front">${icon('create:cogwheel')}${icon('minecraft:chest')}${icon('minecraft:diamond')}</div><span class="mc-art-label">INVENTARIO DE IDEAS</span></div></section>
<div class="mc-quicklinks">${[['recipes','minecraft:chest','Atlas de objetos','Recetas, materiales y usos'],['animations','minecraft:book','Aprende mirando','Tutoriales paso a paso'],['projects','create:wrench','Construye algo','Planos 3D y listas de piezas']].map(([v,i,t,d])=>`<button data-view="${v}">${icon(i)}<span><strong>${t}</strong><small>${d}</small></span><b>↗</b></button>`).join('')}</div>
<div class="section-heading"><div><span class="eyebrow">DEL INVENTARIO A TU MUNDO</span><h2>Aprende bloque a bloque</h2></div><button class="btn btn-text" data-view="animations">Ver tutoriales →</button></div>
<div class="mc-featured-lessons">${[['minecraft:chest','LO ESENCIAL','Guardar y mover objetos','Cofres, espacio y tolvas.','4 pasos'],['create:mechanical_press','CREATE','Tu primera prensa','Del lingote a la lámina.','3 pasos'],['minecraft:brewing_stand','MINECRAFT','Prepara una poción','De la base al efecto.','6 pasos']].map(([id,k,t,d,n])=>`<button class="mc-lesson-card" data-view="item/${encodeURIComponent(id)}"><div class="mc-lesson-art">${icon(id)}<span class="mc-play-mark">▶</span></div><div class="mc-lesson-copy"><small>${k} <span>${n}</span></small><h3>${t}</h3><p>${d}</p></div></button>`).join('')}</div>
<div class="mc-bottom-grid"><section class="mc-continue"><div class="compact-section"><span class="eyebrow">TU RUTA DE CREATE</span><span>${percent()}%</span></div><h2>${esc(cur.name)}</h2><progress max="100" value="${percent()}"></progress><button class="btn btn-primary" data-phase="${cur.id}">Continuar mi ruta →</button><button class="btn btn-text" data-view="map">Ver mapa</button></section><section class="mc-magic"><div>${icon('minecraft:ender_pearl')}<span class="eyebrow">UN POCO DE MAGIA</span></div><h2>Mahou Tsukai</h2><p>Tu grimorio de hechizos, rituales y materiales.</p><button class="btn" data-view="mahou">Abrir el grimorio →</button></section></div>`;}

function atlasIcon(m){return m.iconUrl?`<img class="mod-logo" src="${esc(m.iconUrl)}" alt="" loading="lazy" referrerpolicy="no-referrer">`:modIcon(m.id)||`<span class="mod-initial">${esc(m.name.slice(0,2).toUpperCase())}</span>`;}
function lessonCards(list){return `<div class="lesson-grid">${list.map(l=>`<button class="lesson-card blueprint-sheet" data-lesson="${esc(l.id)}"><div class="compact-section"><span>${esc(catalogName(l.modId))}</span><span class="play-badge">▷</span></div>${sceneFigure(l,icons,name,true)}<h3>${esc(l.title)}</h3><div class="lesson-card-foot"><span>${l.steps.length} pasos</span><span>${state.tasks['lesson:'+l.id]?'✓ Visto':'Abrir montaje →'}</span></div></button>`).join('')}</div>`;}
function animationsView(){const l=lessons.find(x=>x.id===selectedLesson);if(l)return lessonView(l);const list=lessons.filter(l=>(lessonMod==='all'||l.modId===lessonMod)&&normalizeSearch(l.title+' '+l.modId+' '+l.summary).includes(normalizeSearch(lessonQuery)));return pageTitle('','Aprende mirando','Elige un objeto y sigue su tutorial a tu ritmo.')+`<div class="catalog-toolbar"><div class="search-field"><span>⌕</span><input type="search" id="lesson-search" aria-label="Buscar demostraciones" placeholder="Prensa, latón, energía, almacenamiento…" value="${esc(lessonQuery)}"></div><select id="lesson-mod" aria-label="Filtrar demostraciones por mod"><option value="all">Todos los mods</option>${[...new Set([...lessons.map(l=>l.modId),...(workshopData.tutorials||[]).flatMap(t=>t.itemIds.map(id=>id.split(':')[0]))])].map(id=>`<option value="${esc(id)}" ${id===lessonMod?'selected':''}>${esc(catalogName(id))}</option>`).join('')}</select></div>${workshop.tutorialLibrary(lessonQuery,lessonMod)}<details class="disclosure mt"><summary>Más esquemas y montajes</summary>${lessonCards(list)}</details><details class="disclosure mt"><summary>Sobre estas animaciones</summary><p>Son esquemas web interactivos basados en las fuentes enlazadas. El Ponder original se ejecuta en Minecraft; una escena de referencia no reproduce todos los bloques, orientaciones ni tiempos del juego.</p></details>`;}
function lessonView(l){return `<div class="lesson-topline"><button class="btn btn-text" data-lesson-back>← Todas las demostraciones</button><button class="btn btn-text" data-guide="${esc(l.modId)}">${esc(catalogName(l.modId))} ↗</button></div><div class="companion-heading"><h1>${esc(l.title)}</h1><span class="badge">${l.steps.length} pasos</span></div><div class="lesson-layout" id="lesson-player"><section class="lesson-main"><div class="scene-stage blueprint-sheet" data-step="0"><div class="scene-legend"><span>ESQUEMA WEB</span><span data-step-counter>1 / ${l.steps.length}</span></div>${sceneFigure(l,icons,name)}<div class="scene-caption"><strong data-step-title>${esc(l.steps[0]?.title)}</strong><p data-step-text>${esc(l.steps[0]?.text)}</p></div></div><div class="playback-bar"><div class="playback-buttons"><button class="btn btn-primary" data-scene-play aria-pressed="false">▶ Reproducir</button><button class="icon-button" data-scene-restart aria-label="Reiniciar animación">↺</button><button class="icon-button" data-scene-next="-1" aria-label="Paso anterior">‹</button><button class="icon-button" data-scene-next="1" aria-label="Paso siguiente">›</button><select data-scene-speed aria-label="Velocidad de reproducción"><option value=".5">0.5×</option><option value="1" selected>1×</option><option value="1.5">1.5×</option><option value="2">2×</option></select></div><div class="timeline-row"><input type="range" min="0" max="${l.steps.length*6}" step=".1" value="0" data-scene-timeline aria-label="Progreso de la demostración"><span data-scene-clock>0 / ${l.steps.length*6} s</span></div></div><section class="lesson-materials panel"><div class="panel-header"><h3>Componentes del montaje</h3></div><div class="panel-body recipe-process">${l.items.map(id=>`<button class="ingredient-chip" data-item="${esc(id)}">${icon(id)}<span>${esc(name(id))}</span></button>`).join('')}</div></section></section><aside class="lesson-steps paper-panel"><h2>Pasos</h2><ol>${l.steps.map((step,i)=>`<li><button data-lesson-step="${i}" class="${i===0?'active':''}" ${i===0?'aria-current="step"':''}><span>${i+1}</span><div><strong>${esc(step.title)}</strong><p>${esc(step.text)}</p></div></button></li>`).join('')}</ol><label class="check-inline lesson-done"><input type="checkbox" data-lesson-done="${esc(l.id)}" ${state.tasks['lesson:'+l.id]?'checked':''}> Marcar como visto</label></aside></div><div class="guide-support-grid"><section class="panel"><div class="panel-header"><h3>Antes de arrancar</h3></div><div class="panel-body"><ul class="useful-list">${l.checklist.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></div></section><section class="panel"><div class="panel-header"><h3>Si no funciona</h3></div><div class="panel-body"><ul class="useful-list">${l.pitfalls.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></div></section></div>${l.nativePonder?.available?`<div class="native-ponder panel"><span class="keycap">W</span><div><h3>Ver el Ponder original en Minecraft</h3><p>Mantén la tecla de Ponder sobre <strong>${esc(name(l.nativePonder.itemId||l.items[0]))}</strong> en tu inventario o JEI. W es el control predeterminado.</p></div></div>`:''}<details class="disclosure mt"><summary>Fuentes y alcance</summary><p>Esquema ilustrativo: los tiempos del reproductor no son tiempos de fabricación. La disposición exacta se consulta en Ponder o en el manual del mod.</p>${l.layout?`<p>${esc(typeof l.layout==='string'?l.layout:JSON.stringify(l.layout))}</p>`:''}<a href="${esc(l.sourceUrl)}" target="_blank" rel="noopener noreferrer" class="btn btn-text">${esc(l.sourceLabel||'Fuente de la demostración')} ↗</a></details>`;}
function officialMediaView(){return (animationEvidence.verifiedExternalMedia||[]).map(m=>`<details class="disclosure native-media"><summary>Vídeo del autor: ${esc(m.title)}</summary><p>${esc(m.author)} · Showcase de 2022; no corresponde a las recetas de ATM10 8.1.</p><div class="video-host"><button class="btn btn-secondary" data-load-video="${esc(m.id)}">▶ Cargar vídeo original</button></div><a class="btn btn-text" href="${esc(m.watchUrl)}" target="_blank" rel="noopener noreferrer">Abrir en YouTube ↗</a></details>`).join('');}
function modGuideView(){if(selectedGuide==='mahoutsukai')return mahou.view();const m=atlas.find(m=>m.id===selectedGuide);if(!m)return pageTitle('','Mod no encontrado','')+'<button class="btn" data-view="mods">Volver a la biblioteca</button>';const manifest=mods.find(x=>x.id===m.id),modLessons=lessons.filter(l=>l.modId===m.id),modRecipes=recipes.filter(r=>r.source.modId===m.id),relatedRoutes=pack.routes.filter(r=>r.mods.includes(m.id));return `<div class="lesson-topline"><button class="btn btn-text" data-view="mods">← Biblioteca de mods</button><label class="check-inline"><input type="checkbox" data-mod-check="${esc(m.id)}" ${state.mods[m.id]?'checked':''}> En mi mesa</label></div><div class="mod-guide-header">${atlasIcon(m)}<div><span class="eyebrow">${esc(atlasCategories[m.category]||m.category)}${manifest?.version?' · '+esc(manifest.version):''}</span><h1>${esc(m.name)}</h1><p>${esc(m.summary)}</p></div></div><div class="guide-quick-actions">${modRecipes.length?`<button class="btn btn-primary" data-addon-recipes="${esc(m.id)}">▦ ${fmt(modRecipes.length)} recetas</button>`:''}${m.id==='create'?'<button class="btn" data-view="routes">Ruta de Create · 8 etapas</button>':''}${relatedRoutes.map(r=>`<button class="btn" data-pack-route="${esc(r.id)}">⌘ ${esc(r.name)}</button>`).join('')}</div>${modLessons.length?`<section class="workbench-section"><div class="section-heading"><h2>Ver cómo funciona</h2></div>${lessonCards(modLessons)}</section>`:''}${m.id==='create'?officialMediaView():''}<section class="guide-walkthrough"><div class="section-heading"><h2>${m.detailLevel==='support'?'Uso en el modpack':'Guía de uso'}</h2><span class="list-count">${m.firstSteps.filter((_,i)=>state.tasks['guide:'+m.id+':'+i]).length} / ${m.firstSteps.length}</span></div><div class="guide-step-grid">${m.firstSteps.map((step,i)=>{const k='guide:'+m.id+':'+i;return `<article class="guide-step paper-panel ${state.tasks[k]?'completed':''}"><div class="compact-section"><span class="step-index">${String(i+1).padStart(2,'0')}</span><label class="check-inline"><input type="checkbox" data-task="${esc(k)}" ${state.tasks[k]?'checked':''}> Listo</label></div>${step.items?.length?`<div class="guide-step-items">${step.items.filter(id=>icons[id]).slice(0,4).map(id=>`<button class="item-shortcut" data-item="${esc(id)}" title="${esc(name(id))}">${icon(id)}</button>`).join('')}</div>`:''}<h3>${esc(step.title)}</h3><p>${esc(step.text)}</p></article>`;}).join('')}</div></section>${workshop.guideExtras(m)}${m.tips?.length?`<section class="panel mt"><div class="panel-header"><h3>${m.detailLevel==='support'?'Configuración y compatibilidad':'Para evitar atascos'}</h3></div><div class="panel-body"><ul class="useful-list">${m.tips.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></div></section>`:''}${m.related?.length?`<section class="workbench-section"><div class="section-heading"><h2>Mods relacionados</h2></div><div class="related-mods">${m.related.map(id=>atlas.find(x=>x.id===id)).filter(Boolean).map(r=>`<button class="btn" data-guide="${esc(r.id)}">${esc(r.name)} →</button>`).join('')}</div></section>`:''}<details class="disclosure mt"><summary>Documentación y versión</summary><p>${esc(manifest?.filename||'ATM10 8.1')} · ${m.detailLevel==='guide'?'Guía editorial basada en las fuentes del mod.':m.detailLevel==='support'?'Componente de soporte; no tiene una ruta de fabricación independiente.':'Ficha de consulta. La documentación del autor amplía sus funciones.'}</p>${m.sources.map(src=>`<a class="btn btn-text" href="${esc(src.url)}" target="_blank" rel="noopener noreferrer">${esc(src.label)} ↗</a><br>`).join('')}</details>`;}

function routesView(){return pageTitle('UN OBJETIVO A LA VEZ','Ruta de progreso','')+`<div class="toolbar"><div class="tabs"><button class="tab ${routeScope==='create'?'active':''}" data-route-scope="create">Create · 8 etapas</button><button class="tab ${routeScope==='pack'?'active':''}" data-route-scope="pack">Otros mods · ${pack.routes.length} rutas</button><button class="tab ${routeScope==='star'?'active':''}" data-route-scope="star">La ATM Star</button></div><span class="list-count">${routeScope==='create'?`${totalDone()} de ${totalTasks()} objetivos`:routeScope==='pack'?'Ramas complementarias':'Endgame del pack 8.1'}</span></div>`+(routeScope==='create'?`<div class="phase-grid">${phases.map((p,i)=>`<article class="phase-card ${p.id===currentPhase().id?'current':''}"><div class="phase-card-head"><span class="step-number">${String(i+1).padStart(2,'0')}</span><div><div class="eyebrow" style="font-size:8px">${p.level}</div><h3>${p.name}</h3><p>${p.subtitle}</p><div class="phase-tags"><span class="badge ${p.id===currentPhase().id?'gold':'muted'}">${completed(p)===p.tasks.length?'COMPLETADO':p.id===currentPhase().id?'SIGUIENTE ETAPA':'PENDIENTE'}</span></div></div></div><div class="phase-card-bottom"><span>${completed(p)} / ${p.tasks.length} objetivos</span><button class="btn btn-text" data-phase="${p.id}">Explorar etapa →</button></div></article>`).join('')}</div>`:routeScope==='pack'?`<div class="phase-grid">${pack.routes.map((r,i)=>{const done=r.steps.filter(t=>state.tasks['pack:'+t.id]).length;return `<article class="phase-card"><div class="phase-card-head"><span class="step-number">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(r.name)}</h3><p>${esc(r.purpose)}</p><div class="phase-tags">${r.mods.slice(0,3).map(m=>`<span class="badge muted">${esc(m)}</span>`).join('')}</div></div></div><div class="phase-card-bottom"><span>${done} / ${r.steps.length} objetivos</span><button class="btn btn-text" data-pack-route="${r.id}">Abrir ruta →</button></div></article>`;}).join('')}</div>`:starView());}
function starView(){const r=pack.starRecipe;return `<div class="two-col"><div class="stack"><div class="panel"><div class="panel-header"><span class="next-icon">✧</span><div><h3>ATM Star · Runic Star Altar</h3><p>La receta final de la versión 8.1</p></div></div><div class="panel-body"><div class="note-box"><strong>La estrella se fabrica en el Star Altar de Modern Industrialization.</strong><br>${esc(r.note)}</div><div class="planner-summary"><span><b>${fmt(r.euPerTick)}</b> EU/t</span><span><b>${r.ticks}</b> ticks de receta</span><span>Infraestructura + ${r.inputs.length} entradas</span></div><ul class="checklist">${r.inputs.map((i,n)=>`<li class="check-item ${state.tasks['star:'+n]?'completed':''}"><input type="checkbox" id="star-${n}" data-task="star:${n}" ${state.tasks['star:'+n]?'checked':''}><label for="star-${n}">${fmt(i.count)} × ${esc(i.name)}${i.components?`<small>Componentes obligatorios: ${esc(i.components)}</small>`:''}</label></li>`).join('')}</ul><a class="btn btn-text" href="${esc(r.source)}" target="_blank" rel="noopener noreferrer">Consultar receta oficial ↗</a></div></div>${pack.starAltarBuild?`<div class="panel"><div class="panel-header"><h3>Construir el altar</h3></div><div class="panel-body"><p class="muted" style="font-size:12px">El altar es una estructura multibloque. Consulta la definición del pack y la vista previa dentro del juego para orientación, bloques y hatches.</p><details class="disclosure"><summary>Ver desglose de construcción investigado</summary><pre class="raw-json">${esc(JSON.stringify(pack.starAltarBuild,null,2))}</pre></details></div></div>`:''}</div><div class="stack"><div class="panel"><div class="panel-header"><h3>Las piezas del endgame</h3></div><div class="panel-body">${pack.starComponents.map(s=>`<details class="disclosure"><summary>${esc(s.name)}</summary><p>${esc(s.goal)}</p><div class="phase-tags">${s.mods.map(m=>`<span class="badge muted">${esc(m)}</span>`).join('')}</div><a class="btn btn-text" href="${esc(s.source)}" target="_blank" rel="noopener noreferrer">Fuente de componentes ↗</a></details>`).join('')}</div></div><div class="note-box">Marca recursos cuando los tengas preparados. La web no lee tu inventario del servidor.</div></div></div>`;}
function phaseDialog(id){const p=phases.find(x=>x.id===id);if(!p)return;const n=phases.indexOf(p);showDialog(`${String(n+1).padStart(2,'0')} / ${p.name}`,p.level,`<p>${p.description}</p><h3>Objetivos de esta etapa</h3><ul class="checklist">${p.tasks.map(t=>{const k=p.id+':'+t[0];return `<li class="check-item ${state.tasks[k]?'completed':''}"><input type="checkbox" id="task-${t[0]}" data-task="${k}" ${state.tasks[k]?'checked':''}><label for="task-${t[0]}">${t[1]}<small>${t[2]}</small></label></li>`;}).join('')}</ul>${lessons.filter(l=>l.modId==='create'&&l.items.some(id=>p.items.includes(id))).slice(0,3).map(l=>`<button class="btn btn-secondary" data-lesson="${esc(l.id)}">▷ ${esc(l.title)}</button>`).join('')}<h3>Componentes</h3><div class="recipe-process">${p.items.map(item=>`<button class="ingredient-chip" data-item="${item}">${icon(item)}${esc(name(item))}</button>`).join('')}</div><div class="note-box">${p.tip}</div>${n<phases.length-1?`<button class="btn btn-secondary" data-phase="${phases[n+1].id}">Ver la siguiente etapa →</button>`:''}`);}
function packRouteDialog(id){if(id==='mahou-tsukai'){navigate('mahou/roadmap');return;}const r=pack.routes.find(x=>x.id===id);if(!r)return;showDialog(r.name,'RUTA COMPLEMENTARIA · ATM10 8.1',`<p>${esc(r.purpose)}</p><div class="phase-tags">${Object.entries(r.modVersions||{}).map(([k,v])=>`<span class="badge">${esc(k)} ${esc(v)}</span>`).join('')}</div><h3>Plan de trabajo</h3><ul class="checklist">${r.steps.map(t=>{const k='pack:'+t.id;return `<li class="check-item ${state.tasks[k]?'completed':''}"><input type="checkbox" id="${esc(t.id)}" data-task="${esc(k)}" ${state.tasks[k]?'checked':''}><label for="${esc(t.id)}">${esc(t.title)}<small>${esc(t.detail)}</small>${t.requires.length?`<small>Antes: ${t.requires.map(req=>esc(r.steps.find(s=>s.id===req)?.title||req)).join(' · ')}</small>`:''}</label></li>`;}).join('')}</ul><p class="server-note">${esc(r.ordering)}</p><h3>Fuentes</h3>${r.sources.map((url,i)=>`<a class="btn btn-text" target="_blank" rel="noopener noreferrer" href="${esc(url)}">${i+1}. Misiones / scripts del pack ↗</a><br>`).join('')}`);}
function filteredRecipes(){let list=recipes.filter(r=>r.output?.id);if(recipeScope==='featured')list=featuredRecipes();else if(['create','tech','magic','resources'].includes(recipeScope))list=list.filter(r=>categoryFor(r.source.modId)===recipeScope);else if(recipeScope==='pack')list=list.filter(r=>r.id.startsWith('atm-guide:'));if(recipeMod!=='all')list=list.filter(r=>r.source.modId===recipeMod);const q=recipeQuery.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');if(q)list=list.filter(r=>(name(r.output.id)+' '+engName(r.output.id)+' '+r.output.id+' '+r.id+' '+process(r.type)).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(q));if(recipeScope!=='featured')list.sort((a,b)=>{const aPriority=featured.includes(a.output.id)||disciplines.some(d=>d.items.includes(a.output.id));const bPriority=featured.includes(b.output.id)||disciplines.some(d=>d.items.includes(b.output.id));return Number(bPriority)-Number(aPriority)||name(a.output.id).localeCompare(name(b.output.id),'es');});return list;}

function recipesView(){const catalog=[...addons,...catalogMods].filter((m,i,all)=>all.findIndex(x=>x.modId===m.modId)===i);const toolbar=`<div class="search-field"><span>⌕</span><input id="recipe-search" type="search" value="${esc(recipeQuery)}" placeholder="Buscar objeto…" aria-label="Buscar recetas"><kbd>/</kbd></div><select id="recipe-mod" aria-label="Filtrar por mod"><option value="all">Todos los mods</option>${catalog.map(m=>`<option value="${m.modId}" ${recipeMod===m.modId?'selected':''}>${esc(m.name)}</option>`).join('')}<option value="minecraft" ${recipeMod==='minecraft'?'selected':''}>Minecraft</option><option value="atm10" ${recipeMod==='atm10'?'selected':''}>ATM10</option></select><div class="ws-browser-tabs">${[['all','Todo'],['create','Create +'],['tech','Tecnología'],['magic','Magia'],['resources','Recursos']].map(([id,label])=>`<button data-recipe-scope="${id}" class="${recipeScope===id?'active':''}">${label}</button>`).join('')}</div>`;return workshop.explorer(filteredRecipes(),{toolbar,page:recipePage,query:recipeQuery,mod:recipeMod,scope:recipeScope});}

function recipeCard(r,index=1){return `<article class="recipe-card blueprint-sheet"><div class="recipe-sheet-meta"><span>PL. ${String(index).padStart(3,'0')}</span><span>${esc(catalogName(r.source.modId))}</span></div><button class="recipe-object" data-recipe="${esc(r.id)}" aria-label="Abrir receta de ${esc(name(r.output.id))}"><span class="object-crosshair" aria-hidden="true"></span>${icon(r.output.id)}<span class="object-measure" aria-hidden="true">${fmt(r.output.count)} ${r.output.kind==='fluid'?'mB':r.output.kind==='chemical'?'quím.':'u.'}</span></button><h3>${esc(name(r.output.id))}</h3><p class="recipe-operation">${esc(process(r.type))}${r.calculatorEligible===false?' · condiciones especiales':''}</p><div class="recipe-parts"><span>MATERIALES</span><div>${r.ingredients.slice(0,4).map(i=>{const item=engine.resolve(i,state.selections);return `<span class="part-preview" title="${esc(name(item.id))} · ${fmt(i.count)}">${icon(item.id)}<b>${fmt(i.count)}</b></span>`;}).join('')}${r.ingredients.length>4?`<small>+${r.ingredients.length-4}</small>`:''}</div></div><div class="recipe-meta"><span class="pill-count">${r.output.chance<1?fmt(r.output.chance*100)+' % de éxito':'VER DESPIECE'}</span><button class="btn btn-text" data-recipe="${esc(r.id)}">Desplegar plano ↗</button></div></article>`;}

function showDialog(title,sub,body){$('#dialog-content').innerHTML=`<div class="dialog-header"><div><h2>${esc(title)}</h2><small>${esc(sub)}</small></div><button class="icon-button" data-close aria-label="Cerrar ventana">✕</button></div><div class="dialog-body">${body}</div>`;if(!$('#detail-dialog').open)$('#detail-dialog').showModal();$('#detail-dialog').scrollTop=0;}
function recipeRequirements(r){let html='';if(r.energy!==undefined)html+=`<span><b>${fmt(r.energy)}</b> ${esc(r.energyUnit||'energía declarada')} por operación</span>`;if(r.duration||r.processingTime||r.cookingTime)html+=`<span><b>${fmt(r.duration||r.processingTime||r.cookingTime)}</b> ticks declarados</span>`;if(r.perTickUsage)html+='<span>Consumo químico por tick</span>';let out=html?`<div class="planner-summary">${html}</div>`:'';if(r.catalysts?.length)out+=`<h3>Herramientas y catalizadores reutilizables</h3><div class="recipe-process">${r.catalysts.map(c=>{const item=engine.resolve(c,state.selections);return `<div class="ingredient-chip">${icon(item.id)}<span>${fmt(c.count||1)} × ${esc(name(item.id))}</span></div>`;}).join('')}</div><p class="server-note">Se preparan aparte; no se consumen en cada operación.</p>`;return out;}
function lessonLinks(item,type){const list=lessons.filter(l=>l.items.includes(item)||l.recipeTypes?.includes(type)).slice(0,3);return list.length?`<div class="recipe-lesson-links">${list.map(l=>`<button class="btn btn-secondary" data-lesson="${esc(l.id)}">▷ ${esc(l.title)}</button>`).join('')}</div>`:'';}
function recipeDialog(id){const r=engine.byId.get(id);if(!r)return;const pattern=r.raw?.pattern;const sourceUrl=r.source.url;showDialog(name(r.output.id),`${process(r.type)} · ${r.source.version||'ATM10 8.1'}`,`<div class="recipe-process">${r.ingredients.map(i=>{const resolved=engine.resolve(i,state.selections);return `<div class="ingredient-chip">${icon(resolved.id)}<span>${fmt(i.count)} ${i.kind==='fluid'?'mB de':i.kind==='chemical'?'unid. químicas'+(r.perTickUsage?' / tick':'')+' de':'×'} ${esc(name(resolved.id))}${i.kind==='tag'?`<small class="muted" style="display:block">Alternativa: #${esc(i.id)}</small>`:''}</span></div>`;}).join('')}<span class="process-arrow">→</span><div class="ingredient-chip">${icon(r.output.id)}<span>${fmt(r.output.count)} ${r.output.kind==='fluid'?'mB de':r.output.kind==='chemical'?'unid. químicas de':'×'} ${esc(name(r.output.id))}</span></div></div>${pattern?`<details class="disclosure" open><summary>Patrón de fabricación</summary><div class="craft-grid" style="--cols:${Math.max(...pattern.map(x=>x.length))}">${pattern.join('').split('').map(c=>{const ing=r.raw.key?.[c];const item=ing?.item||ing?.id||(ing?.tag?engine.resolve({id:ing.tag,kind:'tag'},state.selections).id:null);return `<div class="craft-cell" title="${item?esc(name(item)):''}">${item?icon(item):c.trim()?'<span title="Consulta la clave en los datos originales">'+esc(c)+'</span>':''}</div>`;}).join('')}</div></details>`:''}<div class="gap-row"><button class="btn" data-ws-pin-recipe="${esc(r.id)}">Fijar receta en modo juego</button></div>${lessonLinks(r.output.id,r.type)}${recipeRequirements(r)}${r.sequence?`<h3>Secuencia · ${r.loops||1} ciclo${r.loops!==1?'s':''}</h3><ol class="sequence-list">${r.sequence.map(s=>`<li>${esc(process(s.type))}: ${s.ingredients.map(i=>`${i.count} × ${esc(name(engine.resolve(i,state.selections).id))}`).join(', ')||'operación sin ingrediente añadido'}</li>`).join('')}</ol><p>La lista de materiales superior ya incluye todos los ciclos.</p>`:''}${r.heat?`<div class="note-box">${r.heat==='superheated'?'Requiere sobrecalentamiento.':'Requiere calor: quemador de blaze activo bajo la cubeta.'}</div>`:''}${r.output.chance<1?`<div class="note-box mt"><strong>Resultado aleatorio: ${fmt(r.output.chance*100)} % de éxito por intento.</strong><br>Los materiales no garantizan una cantidad final. La calculadora presenta una estimación media.</div>`:''}${r.outputs.length>1?`<details class="disclosure"><summary>Salidas y probabilidades</summary><p>${r.outputs.map(o=>`${o.count} × ${esc(name(o.id))}${o.chance<1?' · '+fmt(o.chance*100)+' %':''}`).join('<br>')}</p></details>`:''}${r.raw?.sourceCost||r.raw?.source_cost||r.sourceCost?`<div class="note-box mt">Coste de Source: ${fmt(r.sourceCost||r.raw.sourceCost||r.raw.source_cost)}. Prepara el sistema de Ars por separado.</div>`:''}${r.experienceCost?`<div class="note-box mt">Experiencia requerida: ${fmt(r.experienceCost)}. Verifica cómo se expresa este coste en el proceso del addon.</div>`:''}${r.warnings?.length?`<div class="note-box mt">${r.warnings.map(esc).join('<br>')}</div>`:''}<div class="gap-row">${r.calculatorEligible===false?'<span class="note-box">Consulta de proceso · cálculo automático no disponible.</span>':`<button class="btn btn-primary" data-plan="${esc(r.output.id)}" data-plan-recipe="${esc(r.id)}">Calcular materiales ↗</button>`}<button class="btn" data-inventory-add="${esc(r.output.id)}">Añadir 1 a mis materiales</button></div><details class="disclosure mt"><summary>Fuente y datos de la receta</summary><p>${esc(r.source.jar||'KubeJS de ATM10 8.1')}<br>${esc(r.source.path||r.id)}</p>${sourceUrl?`<a class="btn btn-text" href="${esc(sourceUrl)}" target="_blank" rel="noopener noreferrer">Consultar archivo de origen ↗</a>`:''}<pre class="raw-json">${esc(JSON.stringify(r.raw,null,2))}</pre></details><p class="server-note"></p>`);}
function itemDialog(id){const r=engine.choose(id,state.preferences);if(r)recipeDialog(r.id);else showDialog(name(id),id,`<p>Este recurso no tiene una receta calculable incluida en el catálogo estático. Consulta su obtención en JEI dentro del servidor.</p><button class="btn btn-primary" data-inventory-add="${esc(id)}">Añadir 1 a mis materiales</button>`);}
function planRequirements(plan){const costs={},catalysts=new Map();for(const {recipe:r,batches}of plan.processes){if(r.energy!==undefined){const unit=r.energyUnit||'energía';costs[unit]=(costs[unit]||0)+r.energy*batches;}if(r.sourceCost)costs.Source=(costs.Source||0)+r.sourceCost*batches;for(const c of r.catalysts||[]){const item=engine.resolve(c,state.selections);const existing=catalysts.get(item.id);if(!existing||existing.count<(c.count||1))catalysts.set(item.id,{id:item.id,count:c.count||1});}}return (Object.keys(costs).length?`<div class="planner-summary">${Object.entries(costs).map(([unit,n])=>`<span><b>${fmt(n)}</b> ${esc(unit)} declarados</span>`).join('')}</div><p class="server-note">Suma de las recetas con coste explícito; no incluye consumo de máquinas sin coste de receta registrado.</p>`:'')+(catalysts.size?`<h4 class="mt">Herramientas reutilizables</h4><div class="recipe-process">${[...catalysts.values()].map(c=>`<span class="ingredient-chip">${icon(c.id)}${c.count} × ${esc(name(c.id))}</span>`).join('')}</div>`:'');}
function plannerView(){const chosen=engine.byId.get(plannerRecipe)||engine.choose(plannerItem,state.preferences);if(chosen?.output.id!==plannerItem)plannerRecipe='';const r=engine.byId.get(plannerRecipe)||engine.choose(plannerItem,state.preferences);if(r)plannerRecipe=r.id;currentPlan=engine.plan(plannerItem,plannerQuantity,{inventory:state.inventory,preferences:state.preferences,selections:state.selections,rootRecipe:plannerRecipe,expand:plannerExpand});const plan=currentPlan;const outputs=[...engine.byOutput.keys()].filter(id=>engine.choose(id)).sort((a,b)=>name(a).localeCompare(name(b),'es'));return pageTitle('PIENSA EN GRANDE. CALCULA PRIMERO.','Planos de fabricación','',`<button class="btn btn-secondary" id="energy-calculator">⚙ Calcular estrés (SU)</button>`)+`<div class="panel"><div class="panel-body"><div class="planner-controls"><div class="field"><label for="plan-item">QUÉ VAMOS A FABRICAR</label><select id="plan-item">${outputs.map(id=>`<option value="${esc(id)}" ${id===plannerItem?'selected':''}>${esc(name(id))} · ${esc(id.split(':')[0])}</option>`).join('')}</select></div><div class="field"><label for="plan-qty">${r?.output.kind==='fluid'?'CANTIDAD (mB)':'CANTIDAD'}</label><input id="plan-qty" type="number" min="1" max="1000000" value="${plannerQuantity}"></div><button class="btn btn-primary" id="save-plan">Guardar plano ↗</button></div><div class="toolbar mt" style="margin-bottom:0"><div class="field" style="flex:1"><label for="plan-recipe">RECETA ELEGIDA</label><select id="plan-recipe" style="width:100%">${engine.candidates(plannerItem).filter(r=>r.calculatorEligible!==false).map(r=>`<option value="${esc(r.id)}" ${r.id===plannerRecipe?'selected':''}>${esc(process(r.type))} · ${r.output.count} u. · ${esc(r.id)}</option>`).join('')}</select></div><label style="font-size:11px"><input id="plan-expand" type="checkbox" ${plannerExpand?'checked':''}> Desglosar subrecetas</label></div></div></div><div class="planner-summary"><span><b>${plan.processes.length}</b> operaciones desglosadas</span><span><b>${plan.leaves.length}</b> insumos por reunir</span><span><b>${Object.keys(plan.used).length}</b> materiales del inventario aplicados</span><span>Recortes y excedentes reutilizados</span></div>${plan.warnings.length?`<div class="note-box" style="margin-bottom:20px">${plan.warnings.map(esc).join('<br>')}</div>`:''}<div class="two-col"><section class="stack"><div><div class="section-heading"><h2>El plano</h2><div class="blueprint-controls"><button class="icon-button" data-plan-zoom="-10" aria-label="Alejar plano">−</button><span id="plan-zoom-label">${planZoom}%</span><button class="icon-button" data-plan-zoom="10" aria-label="Acercar plano">+</button><button class="btn btn-text" data-plan-zoom="reset">Restablecer</button></div></div><div class="tree-board" tabindex="0" aria-label="Plano de dependencias; desplázate para ver todos los materiales"><div class="plan-sheet-heading"><span>DESPIECE / ${esc(name(plannerItem))}</span><span>ATM10 — 8.1</span></div><ul class="tree root" id="plan-tree" style="zoom:${planZoom/100}">${treeNode(plan.tree,true)}</ul><div class="plan-sheet-footer">BRASSBOUND · PLANO DE FABRICACIÓN <span>OBJETIVO: ${fmt(plannerQuantity)} u.</span></div></div></div><div class="panel"><div class="panel-header"><h3>Procesos e infraestructura</h3></div><div class="panel-body"><div class="phase-tags">${plan.machines.map(m=>`<span class="badge">${esc(process(m))}</span>`).join('')||'<p class="muted">El inventario ya cubre este objetivo.</p>'}</div>${planRequirements(plan)}<p class="server-note">Esta lista indica tipos de proceso, no cantidades de máquinas ni tasas de producción. Combustible, energía, herramientas, recipientes retornables y montaje se comprueban aparte.</p>${r?`<button class="btn btn-text mt" data-recipe="${esc(r.id)}">Ver receta del objetivo ↗</button>`:''}</div></div>${Object.keys(plan.assumptions).length?`<div class="panel"><div class="panel-header"><h3>Alternativas de materiales</h3></div><div class="panel-body"><p class="server-note" style="margin-top:0">Selecciones de este plano. Almost Unified puede resolver metales a otro mod dentro del juego.</p>${Object.entries(plan.assumptions).map(([tag,a])=>`<div class="field mt"><label for="tag-${esc(tag)}">#${esc(tag)}</label>${a.options.length?`<select id="tag-${esc(tag)}" data-tag-select="${esc(tag)}">${a.options.map(id=>`<option value="${esc(id)}" ${id===a.id?'selected':''}>${esc(name(id))} · ${esc(id)}</option>`).join('')}</select>`:`<p class="server-note">${a.unresolved?'Sin miembros verificables; se deja como insumo por resolver.':esc(name(a.id))+' · equivalencia propuesta, confirmar en JEI.'}</p>`}</div>`).join('')}</div></div>`:''}</section><section class="stack"><div class="panel"><div class="panel-header"><h3>Tu lista de materiales</h3><span class="badge gold">FALTANTES</span></div><div class="panel-body">${plan.leaves.length?`<div class="table-wrap"><table class="ingredients-list"><thead><tr><th>Material</th><th>Falta</th></tr></thead><tbody>${plan.leaves.sort((a,b)=>name(a.id).localeCompare(name(b.id))).map(l=>`<tr><td><div class="material-name">${icon(l.id)}<span>${esc(name(l.id))}<small class="muted">${l.id.startsWith('#')?'Alternativa por resolver':l.kind==='fluid'?'Fluido':Math.floor(l.count/64)+' stacks + '+(l.count%64)+'*'}</small></span></div></td><td>${fmt(l.count)}${l.kind==='fluid'?' mB':''}</td></tr>`).join('')}</tbody></table></div><p class="server-note">* Equivalencia de 64 unidades; algunos ítems tienen otro tamaño de stack. Los insumos sin subreceta pueden ser componentes ya elaborados.</p>`:'<p class="muted" style="font-size:12px">Tu inventario cubre el objetivo. Los materiales no se descuentan hasta que los edites.</p>'}<button class="btn btn-secondary" id="copy-materials">Copiar lista</button><button class="btn btn-text mt" data-view="inventory">Actualizar mis materiales →</button></div></div><div class="note-box"><strong>Recetas alternativas</strong><br>Cambia un proceso desde «Recetas intermedias» si ya dispones de otra máquina.</div><details class="panel"><summary class="panel-header" style="cursor:pointer;font-size:12px">Recetas intermedias</summary><div class="panel-body">${[...new Set(plan.processes.map(p=>p.recipe.output.id))].filter(i=>i!==plannerItem&&engine.candidates(i).length>1).slice(0,30).map(i=>`<div class="field mt"><label>${esc(name(i))}</label><select data-subrecipe="${esc(i)}" aria-label="Receta para ${esc(name(i))}">${engine.candidates(i).filter(r=>r.calculatorEligible!==false).map(c=>`<option value="${esc(c.id)}" ${(state.preferences[i]||engine.choose(i)?.id)===c.id?'selected':''}>${esc(process(c.type))} · ${esc(c.id)}</option>`).join('')}</select></div>`).join('')||'<p class="server-note">No hay alternativas intermedias en este plano.</p>'}</div></details></section></div>`;}
function treeNode(n,root=false){return `<li><div class="tree-node ${root?'goal':''} ${n.raw?'raw':''}">${icon(n.id)}<div>${esc(name(n.id))}<small>${n.available?'✓ Cubierto con inventario / excedentes':n.recipe?`${n.batches} tanda${n.batches!==1?'s':''} · ${esc(process(n.type))}${n.estimated?' · estimación':''}`:n.kind==='fluid'?'Aportar fluido':n.id.startsWith('#')?'Alternativa por resolver':'Conseguir o preparar'}${n.stock?' · '+fmt(n.stock)+' en inventario':''}</small></div><span class="tree-qty">×${fmt(n.count)}</span></div>${n.children.length?`<ul class="tree">${n.children.map(c=>treeNode(c)).join('')}</ul>`:''}</li>`;}
function inventoryView(){const entries=Object.entries(state.inventory).filter(([,v])=>v>0).sort((a,b)=>name(a[0]).localeCompare(name(b[0])));return pageTitle('SABER QUÉ TIENES ES EL PRIMER PASO','Mis materiales','Las cantidades registradas se descuentan del cálculo de materiales.')+`<form class="inventory-form" id="inventory-form"><input id="inventory-item" list="items-list" placeholder="Busca un recurso o escribe su ID (minecraft:iron_ingot)" required aria-label="Material a añadir"><input id="inventory-quantity" type="number" min="1" max="1000000" value="1" required aria-label="Cantidad a añadir"><button class="btn btn-primary" type="submit">Añadir material +</button><datalist id="items-list">${[...new Set([...engine.byOutput.keys(),...recipes.flatMap(r=>r.ingredients.filter(i=>i.kind==='item').map(i=>i.id))])].sort((a,b)=>name(a).localeCompare(name(b))).map(id=>`<option value="${esc(id)}">${esc(name(id))}</option>`).join('')}</datalist></form>${entries.length?`<div class="panel"><div class="table-wrap"><table class="ingredients-list"><thead><tr><th>Material</th><th>Identificador</th><th>Cantidad disponible</th><th></th></tr></thead><tbody>${entries.map(([id,qty])=>`<tr><td><div class="material-name">${icon(id)}${esc(name(id.replace(/^fluid:/,'')))}</div></td><td><small class="muted">${esc(id)}</small></td><td><input type="number" aria-label="Cantidad de ${esc(name(id))}" min="0" max="1000000" value="${qty}" data-inventory-edit="${esc(id)}"></td><td><button class="icon-button" data-inventory-remove="${esc(id)}" aria-label="Quitar ${esc(name(id))}">×</button></td></tr>`).join('')}</tbody></table></div></div>`:'<div class="empty-state"><h3>Sin materiales registrados</h3><p>Añade un material para descontarlo en tus planos.</p></div>'}<div class="note-box mt">Para fluidos usa el ID con prefijo <strong>fluid:</strong>, por ejemplo <strong>fluid:minecraft:water</strong>, y anota milibuckets (mB). Un cubo equivale a 1,000 mB.</div>`;}
function modsView(){const list=filterAtlas(atlas,{query:modQuery,category:atlasCategory,scope:modScope,favorites:state.mods});const size=30;atlasPage=Math.min(atlasPage,Math.max(0,Math.ceil(list.length/size)-1));return pageTitle('','Biblioteca de mods','')+`<div class="catalog-toolbar"><div class="search-field"><span>⌕</span><input type="search" id="mod-search" value="${esc(modQuery)}" placeholder="Buscar un mod o una función…" aria-label="Buscar mods"></div><select id="atlas-category" aria-label="Categoría del mod">${Object.entries(atlasCategories).map(([id,label])=>`<option value="${id}" ${id===atlasCategory?'selected':''}>${label}</option>`).join('')}</select></div><div class="folder-tabs">${[['play','Para jugar'],['all','Todo el modpack'],['guides','Guías detalladas'],['saved','En mi mesa'],['integrations','Conexiones']].map(([id,label])=>`<button class="folder-tab ${modScope===id?'active':''}" data-mod-scope="${id}">${label}</button>`).join('')}</div>${modScope==='integrations'?`<div class="phase-grid mt">${pack.integrations.map(i=>`<article class="mod-card"><span class="eyebrow">${esc(i.from)} → ${esc(i.to)}</span><h3>${esc(i.use)}</h3><p>${esc(i.status)}</p><a href="${esc(i.source)}" target="_blank" rel="noopener noreferrer">Referencia ↗</a></article>`).join('')}</div>`:`<div class="archive-heading"><span>${list.length} entradas</span><span>ATM10 8.1</span></div><div class="atlas-grid">${list.slice(atlasPage*size,(atlasPage+1)*size).map(m=>{const n=recipes.filter(r=>r.source.modId===m.id).length;return `<article class="atlas-card paper-panel"><div class="atlas-card-head">${atlasIcon(m)}<label class="favorite-toggle" title="Guardar en mi mesa"><input type="checkbox" data-mod-check="${esc(m.id)}" aria-label="Guardar ${esc(m.name)} en mi mesa" ${state.mods[m.id]?'checked':''}><span>☆</span></label></div><span class="atlas-category">${esc(atlasCategories[m.category]||m.category)}</span><h3>${esc(m.name)}</h3><p>${esc(m.summary)}</p><div class="atlas-card-meta"><span>${m.detailLevel==='guide'?'Guía detallada':m.detailLevel==='support'?'Soporte':'Ficha de uso'}</span>${n?`<span>${fmt(n)} recetas</span>`:''}</div><button class="btn btn-primary" data-guide="${esc(m.id)}">${m.detailLevel==='guide'?'Abrir guía':'Abrir ficha'} →</button></article>`;}).join('')}</div>${list.length?`<div class="pagination"><button class="btn btn-small" data-atlas-page="${atlasPage-1}" ${atlasPage===0?'disabled':''}>← Anterior</button><span>${atlasPage+1} / ${Math.ceil(list.length/size)}</span><button class="btn btn-small" data-atlas-page="${atlasPage+1}" ${(atlasPage+1)*size>=list.length?'disabled':''}>Siguiente →</button></div>`:'<div class="empty-state">No hay mods con este filtro.</div>'}`}`;}

function notesView(){return pageTitle('QUE NINGUNA IDEA SE QUEDE ATRÁS','Mi bitácora','',`<span class="saved-label">${esc(crew.status())}</span>`)+`<div class="two-col"><div class="panel"><div class="panel-header"><h3>Notas</h3></div><div class="panel-body"><textarea class="notes-area" id="personal-notes" placeholder="Coordenadas de mi taller, ideas para automatizar, pendientes del servidor…" aria-label="Mis notas">${esc(state.notes)}</textarea><p class="server-note">Se guarda mientras escribes. Con tu jugador vinculado, se sincroniza entre tus dispositivos. Solo tú puedes ver estas notas.</p></div></div><div class="panel"><div class="panel-header"><h3>Planos guardados</h3><span class="badge">${state.plans.length}</span></div><div class="panel-body">${state.plans.length?state.plans.map((p,i)=>`<div class="feature-row"><div style="flex:1"><h4>${esc(p.name)}</h4><p>${fmt(p.quantity)} × ${esc(name(p.item))}</p><button class="btn btn-text" data-open-plan="${i}">Abrir plano →</button></div><button class="icon-button" data-delete-plan="${i}" aria-label="Eliminar plano ${esc(p.name)}">×</button></div>`).join(''):'<p class="muted" style="font-size:12px">Tu primer plano aparecerá aquí.<br>Abre Planos de fabricación y pulsa Guardar plano.</p>'}</div></div></div><div class="panel mt"><div class="panel-body"><h3>Respaldo de progreso</h3><p class="server-note">El respaldo incluye objetivos, materiales, notas, mods y planos. Importar combina el avance; las notas se conservan y los inventarios coincidentes toman el valor mayor.</p><div class="note-actions"><button class="btn btn-secondary" id="export-data">↓ Exportar respaldo</button><button class="btn" id="import-data">↑ Importar respaldo</button></div></div></div>`;}
function sourcesView(){return pageTitle('CONSTRUIR SOBRE DATOS CLAROS','Fuentes, versión y alcance','Investigado para tu partida en All the Mods 10 8.1. Aquí puedes comprobar de dónde sale la información y qué sigue dependiendo de tu servidor.')+`<div class="stats-grid"><div class="stat"><div class="stat-label">Modpack</div><div class="stat-value">8.1<small>ATM10</small></div></div><div class="stat"><div class="stat-label">Minecraft</div><div class="stat-value">1.21.1</div></div><div class="stat"><div class="stat-label">Create</div><div class="stat-value">6.0.10</div></div><div class="stat"><div class="stat-label">Recetas en el catálogo</div><div class="stat-value">${fmt(recipes.length)}</div></div></div><div class="note-box" style="margin-bottom:24px"><strong>Catálogo estático, progreso personal.</strong><br>Las recetas provienen de los JAR exactos de Minecraft, Create, sus addons y otros mods seleccionados del pack, con modificaciones seleccionadas del ZIP oficial. No se ha iniciado el servidor para resolver todo KubeJS, Almost Unified, recetas dinámicas o cambios del administrador. Confirma en JEI cuando haya diferencias. La web no lee chunks, inventarios ni misiones del servidor.</div><div class="mh-callout"><strong>Mahou Tsukai 1.36.27</strong> · 53 rituales, 32 crafteos, 458 ajustes cotejados. <button class="btn btn-text" data-view="mahou/settings">Ver fuentes y diferencias →</button></div><div class="sources-list">${sources.map(s=>`<article class="source-item"><h3>${s.title}</h3><p>${s.description}</p><a href="${s.url}" target="_blank" rel="noopener noreferrer">Consultar fuente ↗</a></article>`).join('')}</div><div class="panel mt"><div class="panel-header"><h3>Qué incluye esta edición</h3></div><div class="panel-body"><p class="server-note" style="margin-top:0">${atlas.length} fichas de mods y recursos, ${atlas.filter(m=>m.detailLevel==='guide').length} guías detalladas y ${lessons.length} demostraciones web; 8 etapas de Create con 40 objetivos; ${pack.routes.length} rutas complementarias; ${addons.length-1} addons e integraciones de Create y ${catalogMods.length} mods adicionales con recetas; catálogo estático con alternativas; planos con inventario y desglose recursivo; ruta de la ATM Star. Los objetivos y su orden son una síntesis editorial, no una importación de tu libro de misiones.</p><details class="disclosure mt"><summary>Límites de cálculo y verificación</summary><p>${pack.warnings.map(esc).join('<br>')}</p><p>El cálculo se detiene ante ciclos, fluidos, recetas ausentes o límites de complejidad; esos nodos quedan como insumos. Los excedentes deterministas se reutilizan y los resultados aleatorios son promedios. No calcula dimensiones de fábrica, combustible, velocidad, herramientas ni retornos de recipientes.</p></details><details class="disclosure"><summary>Cobertura de los nuevos mods</summary><p>${catalogMods.map(m=>esc(m.name)+' '+esc(m.version)+' · '+fmt(m.recipeCount)+' recetas').join('<br>')}</p><p>Los tipos no interpretables no entran en el cálculo. Las recetas informativas con condiciones especiales se distinguen en su ficha.</p></details><details class="disclosure"><summary>Animaciones y Ponder</summary><p>Las demostraciones son esquemas web interactivos. No ejecutan Minecraft ni el renderer de Ponder. Sus fuentes, componentes y condiciones figuran en cada lección. El vídeo del autor de Create se reproduce desde YouTube y está identificado como showcase de 2022.</p><a href="data/animation-evidence.json" class="btn btn-text" target="_blank">Evidencia de las escenas ↗</a></details><details class="disclosure"><summary>Créditos y archivos</summary><p>Tipografía Minecraft de Idrees Hassan, recreación bajo SIL OFL 1.1. <a href="licenses/minecraft-ui/ATTRIBUTION.txt" target="_blank" rel="noopener noreferrer">Recursos y atribuciones ↗</a>. Interacciones inspiradas en <a href="https://www.cretania.net/wiki/" target="_blank" rel="noopener noreferrer">la wiki de Cretania</a>; escenas implementadas para Brassbound.</p><p>Minecraft pertenece a Mojang/Microsoft; Create y sus recursos pertenecen a sus autores. Los iconos se usan como referencia de sus objetos. Brassbound es una guía independiente sin afiliación. Arte del taller y diseño de esta web creados para esta bitácora.</p><a href="data/icon-attributions.json" target="_blank" class="btn btn-text">Fuentes y licencias de los iconos ↗</a><p>${fmt(iconReport.referencedRenderedIcons||0)} iconos referenciados provienen de modelos o sprites originales. Los modelos que requieren un renderer especial y no pudieron resolverse se marcan como no disponibles.</p><a href="data/catalog-metadata.json" target="_blank" class="btn btn-text">Metadatos del catálogo ↗</a><br><a href="licenses/create-1.21.1-6.0.10/LICENSE.md_create-1.21.1" target="_blank" class="btn btn-text">Licencia de Create y sus recursos ↗</a></details></div></div>`;}
function energyDialog(){showDialog('Capacidad y consumo (SU)','CALCULADORA CINÉTICA · CREATE 6.0.10',`<p>Compara tu consumo con la capacidad de ruedas hidráulicas. Usa las RPM reales de cada máquina.</p><div class="gap-row mt"><div class="field" style="flex:1"><label for="energy-small">Ruedas pequeñas · 256 SU</label><input id="energy-small" type="number" min="0" max="1000" value="2"></div><div class="field" style="flex:1"><label for="energy-large">Ruedas grandes · 512 SU</label><input id="energy-large" type="number" min="0" max="1000" value="0"></div></div><div class="table-wrap mt"><table class="ingredients-list"><thead><tr><th>Máquina</th><th>Cantidad</th><th>RPM</th></tr></thead><tbody>${stress.machines.map((m,i)=>`<tr><td>${esc(name(m.id))}<small class="muted" style="display:block">${m.impact} SU por RPM</small></td><td><input id="energy-count-${i}" aria-label="Cantidad de ${esc(name(m.id))}" type="number" min="0" max="1000" value="${i===0?1:0}"></td><td><input id="energy-rpm-${i}" aria-label="RPM de ${esc(name(m.id))}" type="number" min="1" max="256" value="32"></td></tr>`).join('')}</tbody></table></div><button class="btn btn-primary" id="calculate-energy">Calcular capacidad</button><div id="energy-result" class="mt" role="status"></div><div class="note-box mt">${esc(stress.scope)} Las ruedas deben estar funcionando y conectadas a la misma red. Engranajes y controladores cambian RPM, no crean capacidad.</div><details class="disclosure"><summary>Planificar vapor</summary><p>Para una caldera activa y con agua continua: nivel = mínimo entre 18, tanques ÷ 4 redondeado hacia abajo, agua en mB/t ÷ 10 redondeado hacia abajo y nivel de calor. Un quemador calentado aporta 1; sobrecalentado, 2. Capacidad aprovechada = 16,384 × mínimo(motores, nivel). El régimen pasivo y el arranque se revisan aparte en Ponder.</p><a class="btn btn-text" target="_blank" rel="noopener noreferrer" href="${stress.sourceUrls[1]}">Fuente exacta del cálculo ↗</a></details>`);calculateEnergy();}
function calculateEnergy(){const cap=clampCount($('#energy-small').value)*256+clampCount($('#energy-large').value)*512;let demand=0;const warnings=[];stress.machines.forEach((m,i)=>{const count=clampCount($('#energy-count-'+i).value),rpm=clampCount($('#energy-rpm-'+i).value);demand+=count*rpm*m.impact;if(count&&(!rpm||rpm>256))warnings.push('Las RPM deben estar entre 1 y 256.');if(count&&m.id==='create:mechanical_mixer'&&rpm<32)warnings.push('El mezclador requiere al menos 32 RPM.');});$('#energy-result').innerHTML=`<div class="planner-summary"><span>Capacidad: <b>${fmt(cap)} SU</b></span><span>Consumo: <b>${fmt(demand)} SU</b></span></div><div class="note-box"><strong>${cap>=demand?'Margen disponible: '+fmt(cap-demand)+' SU':'Sobrecarga: faltan '+fmt(demand-cap)+' SU'}</strong>${warnings.length?'<br>'+[...new Set(warnings)].map(esc).join('<br>'):''}</div>`;}
function addInventory(id,n=1){state.inventory[id]=clampCount((state.inventory[id]||0)+n);save();toast(`${name(id)} añadido a tus materiales`);if(view==='inventory'||view==='planner')render();}
function download(filename,body,type='application/json'){const url=URL.createObjectURL(new Blob([body],{type}));const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function startPlan(id,recipe){if(recipe&&engine.byId.get(recipe)?.calculatorEligible===false){toast('Esta receta requiere revisar condiciones especiales.');recipeDialog(recipe);return;}plannerItem=id;plannerRecipe=recipe||'';$('#detail-dialog').close();navigate('planner');}
document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;const d=b.dataset;
 if(d.mahou){e.preventDefault();navigate('mahou/'+d.mahou);}else if(d.mhScroll){document.getElementById(d.mhScroll)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}else if(d.mhReset!==undefined){mahou.reset();}else if(d.wsPinRecipe&&b.closest('dialog')){state.workspace.pins.recipe=d.wsPinRecipe;save();toast('Receta fijada en modo juego');}else if(d.loadVideo){const media=animationEvidence.verifiedExternalMedia?.find(m=>m.id===d.loadVideo);if(media){const iframe=document.createElement('iframe');iframe.src=media.url;iframe.title=media.title;iframe.allow='accelerometer; autoplay; encrypted-media; gyroscope; picture-in-picture; web-share';iframe.allowFullscreen=true;iframe.referrerPolicy='strict-origin-when-cross-origin';b.closest('.video-host').replaceChildren(iframe);}}else if(d.lesson){$('#detail-dialog').close();navigate('animations/'+d.lesson);}else if(d.lessonBack!==undefined||d.lessonsHome!==undefined){selectedLesson='';navigate('animations');}else if(d.guide){$('#detail-dialog').close();navigate('guide/'+d.guide);}else if(d.atlasPage!==undefined){atlasPage=Number(d.atlasPage);render();window.scrollTo({top:0});}else if(d.planZoom!==undefined){planZoom=d.planZoom==='reset'?100:Math.min(160,Math.max(50,planZoom+Number(d.planZoom)));$('#plan-tree').style.zoom=planZoom/100;$('#plan-zoom-label').textContent=planZoom+'%';}else if(d.discipline){recipeScope=d.discipline;recipeMod='all';recipeQuery='';recipePage=0;navigate('recipes');}else if(d.allRoutes!==undefined){routeScope='pack';navigate('routes');}else if(d.clearFilters!==undefined){recipeScope='all';recipeMod='all';recipeQuery='';recipePage=0;render();}else if(d.view){e.preventDefault();$('#detail-dialog').close();if(d.view==='animations')selectedLesson='';navigate(d.view);}else if(d.phase)phaseDialog(d.phase);else if(d.packRoute)packRouteDialog(d.packRoute);else if(d.recipe)recipeDialog(d.recipe);else if(d.item)itemDialog(d.item);else if(d.plan)startPlan(d.plan,d.planRecipe);else if(d.close!==undefined)$('#detail-dialog').close();else if(d.routeScope){routeScope=d.routeScope;render();}else if(d.recipeScope){recipeScope=d.recipeScope;recipePage=0;render();}else if(d.page!==undefined){recipePage=Number(d.page);render();$('#recipe-results').scrollIntoView({block:'start'});}else if(d.modScope){modScope=d.modScope;atlasPage=0;render();}else if(d.addonRecipes){$('#detail-dialog').close();recipeMod=d.addonRecipes;recipeScope='all';recipeQuery='';recipePage=0;navigate('recipes');}else if(d.modDetail){const m=addons.find(m=>m.modId===d.modDetail);if(m){const n=addonNotes[m.modId];showDialog(m.name,'VERSIÓN '+m.version,`<p>${n.summary}</p><div class="note-box mt">Cuándo explorarlo: ${n.when}</div><button class="btn btn-primary" data-addon-recipes="${m.modId}">Explorar recetas ↗</button>`);}else{const r=pack.routes.find(r=>r.mods.includes(d.modDetail));if(r)packRouteDialog(r.id);else navigate('mods');}}else if(d.inventoryAdd)addInventory(d.inventoryAdd);else if(d.inventoryRemove){const old=state.inventory[d.inventoryRemove];delete state.inventory[d.inventoryRemove];save();render();toast('Material retirado del registro. Puedes volver a añadir '+old+' unidades.');}else if(d.openPlan!==undefined){const p=state.plans[Number(d.openPlan)];plannerQuantity=p.quantity;startPlan(p.item,p.recipe);}else if(d.deletePlan!==undefined){state.plans.splice(Number(d.deletePlan),1);save();render();toast('Plano retirado de la bitácora');}
 if(b.id==='global-search'){recipeScope='all';recipeMod='all';recipeQuery='';navigate('recipes');$('#recipe-search').focus();}if(b.id==='mobile-menu'){const open=$('.sidebar').classList.toggle('open');$('.sidebar').inert=!open;if(open)$('.sidebar .brand').focus();b.setAttribute('aria-expanded',String(open));$('#menu-scrim').hidden=!open;}if(b.id==='menu-scrim'){closeMenu();$('#mobile-menu').focus();}if(b.id==='save-plan'){showDialog('Ponle nombre a tu plano','GUARDAR EN MI BITÁCORA',`<form id="save-plan-form"><div class="field"><label for="plan-name">Nombre del plano</label><input id="plan-name" maxlength="120" value="${esc(plannerQuantity+' × '+name(plannerItem))}" required></div><button class="btn btn-primary" type="submit">Guardar plano</button></form>`);}if(b.id==='copy-materials'){const text=`Brassbound · ATM10 8.1\n${plannerQuantity} × ${name(plannerItem)}\n\nFaltantes:\n${currentPlan.leaves.map(l=>`${fmt(l.count)}${l.kind==='fluid'?' mB':''} × ${name(l.id)} [${l.id}]`).join('\n')}\n\n${currentPlan.warnings.join('\n')}\nCatálogo estático. Confirma en JEI del servidor.`;navigator.clipboard?.writeText(text).then(()=>toast('Lista copiada')).catch(()=>download('materiales-brassbound.txt',text,'text/plain'))||download('materiales-brassbound.txt',text,'text/plain');}if(b.id==='energy-calculator')energyDialog();if(b.id==='calculate-energy')calculateEnergy();if(b.id==='export-data')download('brassbound-atm10-8.1-respaldo.json',JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2));if(b.id==='import-data')$('#import-file').click();
});
document.addEventListener('change',e=>{const el=e.target,d=el.dataset;if(mahou?.input(el))return;if(d.lessonDone){state.tasks['lesson:'+d.lessonDone]=el.checked;save();}if(el.id==='atlas-category'){atlasCategory=el.value;atlasPage=0;render();}if(el.id==='lesson-mod'){lessonMod=el.value;render();}if(d.task){state.tasks[d.task]=el.checked;save();el.closest('.check-item')?.classList.toggle('completed',el.checked);render();}if(d.modCheck){state.mods[d.modCheck]=el.checked;save();toast(el.checked?'Mod marcado para explorar':'Mod desmarcado');if(view==='mods'&&modScope==='saved')render();}if(d.inventoryEdit){state.inventory[d.inventoryEdit]=clampCount(el.value);save();render();}if(d.tagSelect){state.selections[d.tagSelect]=el.value;save();render();}if(d.subrecipe){state.preferences[d.subrecipe]=el.value;save();render();}if(el.id==='recipe-mod'){recipeMod=el.value;recipeScope='all';recipePage=0;render();}if(el.id==='plan-item'){plannerItem=el.value;plannerRecipe='';render();}if(el.id==='plan-qty'){plannerQuantity=Math.max(1,clampCount(el.value));render();}if(el.id==='plan-recipe'){plannerRecipe=el.value;state.preferences[plannerItem]=el.value;save();render();}if(el.id==='plan-expand'){plannerExpand=el.checked;render();}});
let searchTimer;document.addEventListener('input',e=>{const el=e.target;if(mahou?.input(el))return;if(el.id==='lesson-search'){lessonQuery=el.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{const pos=el.selectionStart;render();const input=$('#lesson-search');input.focus();try{input.setSelectionRange(pos,pos);}catch{}},180);return;}if(el.id==='personal-notes'){state.notes=el.value;save();}if(el.id==='recipe-search'||el.id==='mod-search'){const isRecipe=el.id==='recipe-search';const value=el.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{if(isRecipe){recipeQuery=value;recipePage=0;if(recipeQuery&&recipeScope==='featured')recipeScope='all';}else {modQuery=value;atlasPage=0;}const start=el.selectionStart;render();const input=$(isRecipe?'#recipe-search':'#mod-search');input.focus();try{input.setSelectionRange(start,start);}catch{}},180);}});
document.addEventListener('submit',e=>{if(e.target.id==='home-search'){e.preventDefault();recipeQuery=String(new FormData(e.target).get('query')||'').trim();recipeScope='all';recipeMod='all';recipePage=0;navigate('recipes');return;}if(e.target.id.startsWith('mh-')){e.preventDefault();mahou.submit(e.target);return;}if(e.target.id==='inventory-form'){e.preventDefault();let id=$('#inventory-item').value.trim();const qty=clampCount($('#inventory-quantity').value);if(!/^(fluid:)?[a-z0-9_.-]+:[a-z0-9_./-]+$/.test(id)){const match=[...engine.byOutput.keys()].find(x=>name(x).toLowerCase()===id.toLowerCase());if(match)id=match;else{toast('Selecciona un material o usa un ID como minecraft:iron_ingot');return;}}addInventory(id,qty);render();}if(e.target.id==='save-plan-form'){e.preventDefault();state.plans.push({item:plannerItem,quantity:plannerQuantity,recipe:plannerRecipe,name:$('#plan-name').value.trim()||name(plannerItem)});save();$('#detail-dialog').close();render();toast('Plano guardado en tu bitácora');}});
$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>2000000)throw new Error('El respaldo es demasiado grande.');const imported=cleanState(JSON.parse(await file.text()));state.tasks={...state.tasks,...Object.fromEntries(Object.entries(imported.tasks).filter(([,v])=>v))};state.mods={...state.mods,...Object.fromEntries(Object.entries(imported.mods).filter(([,v])=>v))};for(const [id,n]of Object.entries(imported.inventory))state.inventory[id]=Math.max(state.inventory[id]||0,n);state.notes=state.notes===imported.notes?state.notes:[state.notes,imported.notes].filter(Boolean).join('\n\n--- Notas importadas ---\n\n');for(const p of imported.plans)if(!state.plans.some(x=>JSON.stringify(x)===JSON.stringify(p)))state.plans.push(p);state.preferences={...state.preferences,...imported.preferences};state.selections={...state.selections,...imported.selections};state.workspace=mergeWorkspace(state.workspace,imported.workspace);save();render();toast('Respaldo importado y combinado con tu progreso');}catch(err){toast(err.message||'No se pudo leer el respaldo');}e.target.value='';});
function closeMenu(){$('.sidebar').classList.remove('open');$('.sidebar').inert=window.matchMedia('(max-width:960px)').matches;$('#mobile-menu').setAttribute('aria-expanded','false');$('#menu-scrim').hidden=true;}
document.querySelector('.skip-link').addEventListener('click',e=>{e.preventDefault();$('#content').focus();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('.sidebar').classList.contains('open')){closeMenu();$('#mobile-menu').focus();}if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('#detail-dialog').open){e.preventDefault();recipeScope='all';recipeMod='all';recipeQuery='';navigate('recipes');$('#recipe-search').focus();}});
$('#detail-dialog').addEventListener('click',e=>{if(e.target===$('#detail-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
document.addEventListener('error',e=>{if(e.target?.classList?.contains('mod-logo')){const fallback=document.createElement('span');fallback.className='mod-initial';fallback.textContent='◈';e.target.replaceWith(fallback);}},true);

window.matchMedia('(max-width:960px)').addEventListener('change',()=>closeMenu());
window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));
async function init(){try{const files=['recipes','translations','tags','icons','addons-exact','pack-guide','mods','report','stress','mods-catalog','icon-coverage','mod-atlas','animation-scenes','animation-evidence','workshop','mahou'];const data=await Promise.all(files.map(f=>fetch(`data/${f}.json`).then(r=>{if(!r.ok)throw new Error('No se pudo cargar '+f);return r.json();})));[recipes,translations,tags,icons,addons,pack,mods,report,stress,catalogMods,iconReport,atlas,lessons,animationEvidence,workshopData,mahouData]=data;for(const r of pack.recipes.filter(r=>!['mekanism:digital_miner','kubejs:universal_press'].includes(r.id))){recipes.push({id:'atm-guide:'+r.id,type:'atm:'+r.machine,ingredients:r.ingredients.map(i=>({id:i.id.replace(/^#/,''),kind:i.kind==='tag'?'tag':(i.kind==='fluid'||i.kind==='mB')?'fluid':'item',count:i.quantity})),output:{id:r.outputItem,count:r.outputCount,chance:1},outputs:[{id:r.outputItem,count:r.outputCount,chance:1}],source:{modId:'atm10',version:'8.1',url:r.source,path:r.id},raw:r,warnings:[r.notes,r.verification].filter(Boolean),certainty:'atm-override'});}engine=createEngine(recipes,tags);workshop=createWorkshop({data:workshopData,icons,icon,name,engine,recipes,lessons,phases,pack,atlas,state:()=>state,save,render,navigate,recipeCard,recipeDialog,itemDialog,toast,catalogName,process,sceneFigure,download,categoryFor});mahou=createMahou({data:mahouData,icon,name,state:()=>state,navigate});await crew.boot();navigate(location.hash.slice(1)||'home');}catch(err){$('#content').innerHTML=`<div class="empty-state"><h3>No se pudo abrir la bitácora.</h3><p>${esc(err.message)}</p><button class="btn mt" onclick="location.reload()">Volver a intentar</button></div>`;}}
init();
